100	  const usesD1Blob=mediaStrategy==='D1_BLOB';
101	  const storedImages=(await db.prepare(`SELECT id,original_name AS originalName,mime_type AS contentType,byte_size AS sizeBytes,position FROM listing_images WHERE listing_id=?${usesD1Blob?' AND blob_data IS NOT NULL':''}`).bind(listingId).all<any>()).results.map(image=>({...image,url:`/admin/listings/${encodeURIComponent(listingId)}/images/${encodeURIComponent(image.id)}`}));
