126	  if(current.status!=='SUBMITTED')return c.json({error:'listing is no longer awaiting review'},409);
127	  const updated=actionValue==='approve'
128	    ? c.env.DB.prepare("UPDATE listings SET status='APPROVED',rejection_reason=NULL,updated_at=? WHERE id=? AND status='SUBMITTED' AND EXISTS (SELECT 1 FROM users WHERE users.id=listings.owner_id AND users.role='OWNER')").bind(at,listingId)
129	    : c.env.DB.prepare("UPDATE listings SET status='REJECTED',rejection_reason=?,updated_at=? WHERE id=? AND status='SUBMITTED' AND EXISTS (SELECT 1 FROM users WHERE users.id=listings.owner_id AND users.role='OWNER')").bind(reason,at,listingId);
130	  const audit=sourceAuditInsert(c,eventId,listingId,action,reason,at,`l.id=? AND owner.role='OWNER' AND changes()=1 AND l.status=? AND l.updated_at=?`,[listingId,status,at]);
131	  try{
132	    const results=await c.env.DB.batch([updated,audit]);
133	    if(results[0]?.meta?.changes!==1||results[1]?.meta?.changes!==1)return c.json({error:'listing changed during review'},409);
134	  }catch{return c.json({error:'review outcome could not be confirmed'},503);}
135	  const result=await sourceAdminListing(c.env.DB,listingId,c.env.MEDIA_STRATEGY);return result?c.json(result):c.json({message:'Listing not found'},404);
136	}
