242	async function lock(db:D1Database,lid:string) { const token=id(),n=Math.floor(Date.now()/1000);const r=await db.prepare('INSERT INTO listing_locks(listing_id,token,expires_at) VALUES(?,?,?) ON CONFLICT(listing_id) DO UPDATE SET token=excluded.token,expires_at=excluded.expires_at WHERE listing_locks.expires_at < ? RETURNING token').bind(lid,token,n+3600,n).first();return r?token:null; }
243	async function unlock(db:D1Database,lid:string,t:string) {
244	  const correlationId=crypto.randomUUID(),attempts=3;
245	  for(let attempt=0;attempt<attempts;attempt++){
246	    try{await db.prepare('DELETE FROM listing_locks WHERE listing_id=? AND token=?').bind(lid,t).run();}catch{}
247	    try{
248	      const current=await db.prepare('SELECT token,expires_at FROM listing_locks WHERE listing_id=?').bind(lid).first<{token:string;expires_at:number}>();
249	      if(!current||current.token!==t)return;
250	    }catch{}
251	  }
252	  const nowSeconds=Math.floor(Date.now()/1000),expiredAt=nowSeconds-1;
253	  try{await db.prepare('UPDATE listing_locks SET expires_at=? WHERE listing_id=? AND token=?').bind(expiredAt,lid,t).run();}catch{}
254	  try{const current=await db.prepare('SELECT token,expires_at FROM listing_locks WHERE listing_id=?').bind(lid).first<{token:string;expires_at:number}>();if(!current||current.token!==t||current.expires_at<=nowSeconds){console.warn(JSON.stringify({event:'listing_lease_release_deferred_to_expiry',correlationId}));return;}}catch{}
255	  console.error(JSON.stringify({event:'listing_lease_release_unconfirmed',correlationId,attempts}));
256	}
